INSERT INTO orders (
    order_no, user_id, store_id, total_amount, delivery_fee, discount_amount, pay_amount, status, coupon_id, address, phone, remark
) VALUES (
    #{orderNo}, #{userId}, #{storeId}, #{totalAmount}, #{deliveryFee}, #{discountAmount}, #{payAmount}, #{status}, #{couponId}, #{address}, #{phone}, #{remark}
)

mapper.select:
SELECT o.*, s.store_name
FROM orders o
LEFT JOIN stores s ON o.store_id = s.store_id
WHERE o.user_id = #{userId}

    AND o.status = #{status}

ORDER BY o.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM orders o
WHERE o.user_id = #{userId}

    AND o.status = #{status}
